package main

import (
    "fmt"
    "net/http"
    "net/http/httptest"
)

func greet(w http.ResponseWriter, r *http.Request) {
    name := r.URL.Query().Get("name")
    if name == "" {
        name = "гость"
    }
    fmt.Fprintf(w, "Привет, %s!", name)
}

func main() {
    req := httptest.NewRequest("GET", "/greet?name=Go", nil)
    rec := httptest.NewRecorder()
    greet(rec, req)
    fmt.Println(rec.Code)
    fmt.Println(rec.Body.String())
}

package main

import (
    "fmt"
    "net/http"
    "net/http/httptest"
)

func main() {
    mux := http.NewServeMux()
    mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
        fmt.Fprintf(w, "user %s", r.PathValue("id"))
    })

    rec := httptest.NewRecorder()
    mux.ServeHTTP(rec, httptest.NewRequest("GET", "/users/42", nil))
    fmt.Println(rec.Code, rec.Body.String())

    rec2 := httptest.NewRecorder()
    mux.ServeHTTP(rec2, httptest.NewRequest("POST", "/users/42", nil))
    fmt.Println(rec2.Code)
}
